package com.himeros.trustsafety;import com.himeros.shared.outbox.OutboxService;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class TrustSafetyService implements TrustSafetyQuery{private final BlockRepository blocks;private final ReportRepository reports;private final OutboxService outbox;public TrustSafetyService(BlockRepository b,ReportRepository r,OutboxService o){blocks=b;reports=r;outbox=o;}@Transactional public void block(UUID actor,UUID target){if(actor.equals(target))throw new IllegalArgumentException("Cannot block yourself");if(!blocks.existsByBlockerAndBlocked(actor,target)){blocks.save(new Block(actor,target));outbox.append("Block",actor+":"+target,"himeros.trust.user-blocked.v1","himeros.trust.events.v1",actor,Map.of("blockerId",actor,"blockedId",target));}}@Transactional public void unblock(UUID actor,UUID target){blocks.deleteByBlockerAndBlocked(actor,target);}@Transactional public UUID report(UUID actor,UUID target,String reason,String details){if(actor.equals(target))throw new IllegalArgumentException("Cannot report yourself");Report r=reports.save(new Report(actor,target,reason,details));return r.id();}@Override@Transactional(readOnly=true)public boolean blockedEitherWay(UUID a,UUID b){return blocks.existsByBlockerAndBlocked(a,b)||blocks.existsByBlockerAndBlocked(b,a);}@Override@Transactional(readOnly=true)public Set<UUID> excluded(UUID u){Set<UUID> x=new HashSet<>(blocks.blockedBy(u));x.addAll(blocks.blockedMe(u));return x;}}
